W = 4
H, A, G = "HRM-theorie", "Arbeidsrecht", "Gespreksvoering"

# ---------- HRM-theorie MC ----------
mc("hrm4-h01", W, H, "Motivatie bestaat uit intensiteit, richting en volharding. Wat betekent volharding?",
   ["Hoe hard iemand op een moment zijn best doet", "Of de inspanning gericht is op de gewenste resultaten", "Hoe lang iemand de inspanning volhoudt, ook bij tegenslag", "Hoeveel beloning iemand verwacht"], 2,
   "Intensiteit is hoe hard iemand zijn best doet, richting is of de inspanning op de juiste resultaten gericht is (de kwaliteit), en volharding is hoe lang iemand het volhoudt.")
mc("hrm4-h02", W, H, "Je laat schoonmakers zelf hun route door het gebouw indelen. Welke basisbehoefte uit de zelfdeterminatietheorie van Ryan en Deci spreek je daarmee vooral aan?",
   ["Autonomie", "Competentie", "Verbondenheid", "Billijkheid"], 0,
   "De zelfdeterminatietheorie noemt drie basisbehoeften: autonomie (controle over eigen keuzes), competentie (vertrouwen in eigen kunnen) en verbondenheid (ergens bij horen). Zelf je route kiezen is autonomie.")
mc("hrm4-h03", W, H, "Een gastvrouw raakt gedemotiveerd omdat haar collega hetzelfde verdient maar volgens haar veel minder doet. Welke motivatietheorie verklaart dit het best?",
   ["Self-efficacy-theorie", "Doelstellingstheorie", "Billijkheidstheorie", "Zelfdeterminatietheorie"], 2,
   "Volgens de billijkheidstheorie vergelijken mensen zich voortdurend met anderen, en dat beïnvloedt hun motivatie. Als facility manager zorg je dus voor een eerlijke en uitlegbare verdeling van taken en beloning.")
mc("hrm4-h04", W, H, "Wat zegt de doelstellingstheorie?",
   ["Mensen zijn gemotiveerd als ze geloven in hun eigen kunnen", "Specifieke én uitdagende doelen plus feedback leiden tot hogere motivatie", "Mensen vergelijken zichzelf met anderen", "Alleen geld motiveert"], 1,
   "Specifieke en uitdagende doelen met feedback verhogen de motivatie. In de praktijk vertaal je dat naar SMART-doelen in het planningsgesprek. Het geloof in eigen kunnen is de self-efficacy-theorie.")
mc("hrm4-h05", W, H, "Een receptioniste krijgt naast haar huidige werk de verantwoordelijkheid voor het budget van de vergaderservice en mag zelf een leverancier kiezen. Welke interventie is dit volgens de gangbare betekenis?",
   ["Taakroulatie", "Taakverbreding", "Taakverrijking", "Alternatieve werkregeling"], 2,
   "Taakverrijking is meer verantwoordelijkheid en zeggenschap (verticaal). Taakverbreding is meer taken op hetzelfde niveau, taakroulatie is wisselen tussen taken. Deze drie staan op de interventiekaart onder motiveren door taakontwerp.")
mc("hrm4-h06", W, H, "Volgens welke stroming hangt effectief leiderschap af van de situatie, zodat je als leider je stijl aanpast?",
   ["Persoonlijkheidstheorieën", "Gedragstheorieën", "Contingentietheorieën", "Billijkheidstheorieën"], 2,
   "Contingentietheorieën (zoals het model van Fiedler, situationeel leiderschap en de pad-doeltheorie) zeggen dat effectief leiderschap van de situatie afhangt. Persoonlijkheidstheorieën kijken naar kenmerken (Big Five, EQ), gedragstheorieën naar wat iemand doet (taak- of relatiegericht).")
mc("hrm4-h07", W, H, "Je krijgt een nieuwe, enthousiaste gastvrouw zonder ervaring. Welke stijl past volgens situationeel leiderschap het best?",
   ["Delegeren: weinig sturing, weinig ondersteuning", "Instrueren: veel sturing, weinig ondersteuning", "Participeren: weinig sturing, veel ondersteuning", "Laissez-faire: geen sturing"], 1,
   "Situationeel leiderschap: de stijl verandert naarmate iemand ervarener en deskundiger wordt. Bij weinig ervaring en hoge motivatie past instrueren. De vier stijlen (instrueren, overtuigen, participeren, delegeren) zijn de gangbare indeling van Hersey en Blanchard; op de slide stonden ze als afbeelding.")
mc("hrm4-h08", W, H, "Een nieuw samengesteld facilitair team heeft na een paar weken veel discussie over wie waarvoor verantwoordelijk is. In welke fase van teamontwikkeling (Tuckman, gangbare indeling) zit het team?",
   ["Forming", "Storming", "Norming", "Performing"], 1,
   "Storming is de strijd om rollen. Daarna volgen norming (afspraken en normen), performing (presteren) en adjourning (afscheid). Deze fasen stonden als afbeelding op de slide; check ze met de les.")

# ---------- Arbeidsrecht MC ----------
mc("hrm4-a01", W, A, "Wat is het uitgangspunt van art. 7:628 BW?",
   ["Geen arbeid, geen loon", "Geen arbeid, wel loon, tenzij het niet werken in redelijkheid voor rekening van de werknemer komt", "Loon alleen bij ziekte", "Loon alleen als de cao dat regelt"], 1,
   "Het uitgangspunt is geen arbeid, wel loon. Komt het niet werken in redelijkheid voor rekening van de werknemer, zoals bij werkweigering, dan heeft hij geen recht op loon. Lid 5 regelt hoe ver je bij overeenkomst mag afwijken.")
mc("hrm4-a02", W, A, "Een werkgever stelt een facilitair medewerker op non-actief tijdens een intern onderzoek. Moet hij het loon doorbetalen?",
   ["Nee, er wordt niet gewerkt", "Ja, schorsing of op non-actiefstelling komt altijd voor rekening van de werkgever", "Alleen als het onderzoek langer dan een maand duurt", "Alleen als de werknemer onschuldig blijkt"], 1,
   "Schorsing of op non-actiefstelling komt volgens de les altijd voor rekening van de werkgever. Het alternatief is ontslag op staande voet of een andere vorm van ontslag. Ook bedrijfsrisico's komen voor rekening van de werkgever.")
mc("hrm4-a03", W, A, "Hoe lang en hoeveel betaalt de werkgever door bij ziekte van een werknemer met een vast contract (art. 7:629 BW)?",
   ["52 weken, 100% van het loon", "104 weken, 70% van het loon, in het eerste jaar minimaal het minimumloon", "104 weken, 70%, en in beide jaren minimaal het minimumloon", "26 weken, 70% van het loon"], 1,
   "104 weken, 70% van het loon, met een maximum (70% van het maximum dagloon). In de eerste 52 weken minimaal het minimumloon, in de tweede 52 weken niet. Veel cao's vullen aan, maar dat staat niet in de wet.")
mc("hrm4-a04", W, A, "Een zieke werknemer weigert naar de bedrijfsarts te gaan. De werkgever heeft hem gewaarschuwd. Wat kan de werkgever nu doen?",
   ["Het loon staken, zonder terugwerkende kracht", "Het loon opschorten: tijdelijk geen loon, maar met terugwerkende kracht zodra hij zich weer aan de voorschriften houdt", "Hem op staande voet ontslaan", "Niets, een zieke werknemer mag dat weigeren"], 1,
   "Het weigeren van de bedrijfsarts is het niet naleven van een controlevoorschrift (art. 7:629 lid 6 BW): loonopschorting, met terugwerkende kracht zodra hij meewerkt. Loonstaking (lid 3) is voor bijvoorbeeld het belemmeren van genezing of weigeren van passende arbeid, en dan zonder terugwerkende kracht. Eerst waarschuwen (lid 7).")
mc("hrm4-a05", W, A, "In welke week van de ziekte moet de werkgever de ziekmelding bij het UWV doen?",
   ["Week 6", "Week 8", "Week 42", "Week 91"], 2,
   "De tijdlijn: probleemanalyse binnen 6 weken, plan van aanpak uiterlijk 2 weken later (week 8), ziekmelding bij het UWV in week 42, eerstejaarsevaluatie rond week 52, en het re-integratieverslag uiterlijk 13 weken voor het einde (week 91) naar het UWV.")
mc("hrm4-a06", W, A, "Een schoonmaker werkt 4 dagen van 8 uur per week. Hoeveel wettelijke vakantie heeft hij per jaar minimaal (art. 7:634 BW)?",
   ["16 dagen (128 uur)", "20 dagen (160 uur)", "24 dagen", "25 dagen"], 0,
   "Het wettelijke minimum is 4 keer de overeengekomen arbeidsduur per week: 4 × 32 uur = 128 uur, dus 16 werkdagen van 8 uur. Wat contract of cao meer geeft, is bovenwettelijk.")
mc("hrm4-a07", W, A, "Wanneer vervallen de wettelijke vakantiedagen die een werknemer in 2026 heeft opgebouwd (art. 7:640a BW)?",
   ["Op 1 januari 2027", "Op 1 juli 2027", "Op 1 januari 2032", "Nooit, zolang het dienstverband loopt"], 1,
   "Wettelijke dagen vervallen een half jaar na het opbouwjaar, dus op 1 juli 2027. Bovenwettelijke dagen verjaren pas vijf jaar na het opbouwjaar (art. 7:642 BW).")
mc("hrm4-a08", W, A, "Een werknemer krijgt een kind; zijn partner is bevallen. Welk verlof heeft hij met behoud van loon direct na de geboorte (WAZO)?",
   ["Geboorteverlof van 1 keer de arbeidsduur per week, op te nemen binnen 4 weken", "Aanvullend geboorteverlof van 5 weken met volledig loon", "Bevallingsverlof van 10 weken", "Ouderschapsverlof van 26 weken met volledig loon"], 0,
   "Geboorteverlof (art. 4:2 WAZO) is 1 keer de wekelijkse arbeidsduur, binnen 4 weken, met behoud van loon. Het aanvullend geboorteverlof (4:2a) is onbetaald met een UWV-uitkering. Ouderschapsverlof is onbetaald, met voor 9 weken een uitkering als je het opneemt voor het kind 1 jaar is.")

# ---------- Gespreksvoering MC ----------
mc("hrm4-g01", W, G, "Wat kenmerkt een ontwikkelgesprek, in vergelijking met een functionerings- en beoordelingsgesprek?",
   ["Het is een oordeel van de leidinggevende over de afgelopen periode", "Het is tweerichtingsverkeer, toekomstgericht, over talenten, ambities, loopbaan en duurzame inzetbaarheid", "Het gaat alleen over ziekteverzuim", "Het heeft altijd gevolgen voor de beloning"], 1,
   "Het ontwikkelgesprek is toekomstgericht en eindigt met afspraken over ontwikkelacties, bijvoorbeeld in een POP. Het beoordelingsgesprek is een oordeel met mogelijke gevolgen; het functioneringsgesprek gaat over hoe het werk nu gaat.")
mc("hrm4-g02", W, G, "Wat is na de opening de volgorde van het inhoudelijke deel van een ontwikkelgesprek volgens workshop 4?",
   ["Acties, huidige situatie, toekomstperspectief, ontwikkelmogelijkheden", "Huidige situatie, ontwikkelmogelijkheden, toekomstperspectief, acties", "Toekomstperspectief, acties, huidige situatie, ontwikkelmogelijkheden", "Ontwikkelmogelijkheden, acties, huidige situatie, toekomstperspectief"], 1,
   "Eerst de huidige situatie, dan de ontwikkelmogelijkheden, dan het toekomstperspectief en tot slot concrete acties. In het tentamen laat je alle vier de stappen horen.")
mc("hrm4-g03", W, G, "Wat bereid je voor een ontwikkelgesprek voor aan de kant van de organisatie?",
   ["De ambities van de medewerker", "Doorgroeimogelijkheden, opleidingen en nieuwe taken", "De sterke punten van de medewerker", "Het verzuim van de medewerker"], 1,
   "Over de medewerker: sterke punten, ontwikkelpunten, ambities en eerdere afspraken. Over de organisatie: mogelijkheden voor groei, opleidingen, nieuwe taken en doorgroeimogelijkheden.")
mc("hrm4-g04", W, G, "Wanneer is het volgens workshop 4 tijd om te confronteren?",
   ["Bij het eerste gesprek over ontwikkeling", "Als je dezelfde feedback al een paar keer hebt gegeven", "Als de medewerker een opleiding wil", "Nooit, confronteren past niet bij een ontwikkelgesprek"], 1,
   "Confronteren betekent dat je heel goed weet welk gedrag of welke houding je verwacht en de ander verantwoordelijk houdt voor de verandering. Dat past als eerdere feedback niet heeft gewerkt.")
mc("hrm4-g05", W, G, "Welke kernvraag hoort volgens de workshop bij de voorbereiding van een ontwikkelgesprek?",
   ["Hoeveel kost een opleiding?", "Waar staat de medewerker nu, en waar zou hij over drie tot vier jaar kunnen staan?", "Hoe vaak was de medewerker ziek?", "Wie is de beste in het team?"], 1,
   "Je bereidt voor waar de medewerker nu staat en wat zijn perspectief is. Zorg ook voor een rustige omgeving en genoeg tijd, en neem eerdere afspraken mee: hoe concreter (SMART), hoe beter.")
mc("hrm4-g06", W, G, "Een medewerker wil binnen een jaar manager worden, eigenlijk op jouw plek. Wat is volgens de oefencasus jouw opdracht in het gesprek?",
   ["De ambitie direct afwijzen", "Een realistisch perspectief bespreken en de relatie goed houden", "Een promotie beloven om hem te behouden", "Het onderwerp vermijden"], 1,
   "Bij de overambitieuze medewerker bespreek je eerlijk wat realistisch is, zonder hem te demotiveren of de relatie te schaden. Je kunt wel concrete stappen afspreken richting zijn ambitie.")
mc("hrm4-g07", W, G, "Digitalisering en automatisering veranderen facilitaire functies en vragen om bij- en omscholing. Welke externe ontwikkeling is dit volgens de workshop?",
   ["Demografisch", "Technologisch", "Sociaal-cultureel", "Juridisch"], 1,
   "De workshop noemt drie externe ontwikkelingen: demografisch (vergrijzing, langer doorwerken), technologisch (digitalisering) en sociaal-cultureel (nieuwe werkwaarden zoals flexibiliteit en werk-privébalans).")
mc("hrm4-g08", W, G, "Je wilt het ontwikkelgesprek afsluiten. Wat hoort er minimaal bij?",
   ["Een cijfer voor het functioneren", "Een concrete, vastgelegde afspraak (SMART) en een moment om terug te kijken", "Een loonsverhoging", "Een nieuwe functieomschrijving"], 1,
   "Een ontwikkelgesprek eindigt met concrete, vastgelegde afspraken, bijvoorbeeld in een POP, en een datum om terug te kijken. Dat is ook wat de beoordelaar in het tentamen wil horen.")

# ---------- Open vragen ----------
op("hrm4-ho1", W, H, "Kies twee motivatietheorieën uit het college. Leg ze uit en noem bij elke theorie twee concrete interventies voor een schoonmaakteam.",
   "Bijvoorbeeld de zelfdeterminatietheorie (Ryan en Deci): motivatie ontstaat als autonomie, competentie en verbondenheid vervuld zijn. Interventies: schoonmakers zelf hun route laten indelen (autonomie), training in nieuwe machines (competentie), een vast team per locatie (verbondenheid). Doelstellingstheorie: specifieke, uitdagende doelen met feedback verhogen de motivatie. Interventies: SMART-doelen in het planningsgesprek, maandelijks de kwaliteitsscores terugkoppelen. Andere juiste keuzes: billijkheid, self-efficacy, verwachtingstheorie, taakkenmerkenmodel.",
   ["Twee theorieën juist uitgelegd", "Per theorie twee interventies die logisch uit de theorie volgen", "Interventies passen bij een schoonmaakteam"])
op("hrm4-ho2", W, H, "Leg situationeel leiderschap uit. Beschrijf de vier stijlen en bij elke stijl het type medewerker waarbij die past.",
   "Situationeel leiderschap is een contingentietheorie: de behoefte aan een stijl verandert naarmate een medewerker ervarener en deskundiger wordt, dus je past je stijl aan. De gangbare indeling (Hersey en Blanchard): instrueren (veel sturing, weinig ondersteuning) bij weinig ervaring maar wel enthousiasme; overtuigen of coachen (veel sturing, veel ondersteuning) bij enige ervaring en wisselende motivatie; participeren (weinig sturing, veel ondersteuning) bij iemand die het kan maar soms twijfelt; delegeren (weinig sturing, weinig ondersteuning) bij een ervaren, zelfstandige medewerker.",
   ["Kern: stijl aanpassen aan ervaring en deskundigheid", "Vier stijlen met de mate van sturing en ondersteuning", "Bij elke stijl het passende type medewerker"])
op("hrm4-ao1", W, A, "Wat geldt er voor het loon als een werknemer ziek is? Bespreek de duur, de hoogte, en het verschil tussen loonstaking en loonopschorting.",
   "Art. 7:629 BW: 104 weken loondoorbetaling (korter als het contract eerder eindigt of voor de werknemers uit lid 2), 70% van het loon met een maximum van 70% van het maximum dagloon, in de eerste 52 weken minimaal het minimumloon. Maximaal twee wachtdagen als die in de arbeidsovereenkomst staan. Loonstaking (lid 3): bijvoorbeeld bij opzettelijk veroorzaakte ziekte, het belemmeren van genezing of het weigeren van passende arbeid; geen loon, ook niet achteraf. Loonopschorting (lid 6): bij het niet naleven van controlevoorschriften, zoals weigeren naar de bedrijfsarts te gaan; het loon wordt achteraf alsnog betaald zodra de werknemer meewerkt. De werkgever moet eerst waarschuwen (lid 7).",
   ["104 weken en 70%, eerste jaar minimaal minimumloon", "Loonstaking juist uitgelegd met voorbeeld", "Loonopschorting juist uitgelegd met voorbeeld", "Eerst waarschuwen"])
op("hrm4-ao2", W, A, "Beschrijf de stappen van de re-integratie bij langdurige ziekte met de weeknummers. Wat gebeurt er als de werkgever te weinig heeft gedaan?",
   "De werknemer meldt zich ziek en de werkgever meldt het bij de bedrijfsarts. Binnen 6 weken maakt de bedrijfsarts een probleemanalyse. Uiterlijk 2 weken later (week 8) volgt het plan van aanpak met acties van werkgever en werknemer, evaluatieafspraken en een casemanager. Elke 6 tot 8 weken wordt geëvalueerd. In week 42 volgt de ziekmelding bij het UWV, rond week 52 de eerstejaarsevaluatie. Het re-integratieverslag gaat uiterlijk 13 weken voor het einde van de 104 weken (week 91) naar het UWV. Heeft de werkgever te weinig gedaan, dan kan het UWV de loondoorbetaling met maximaal een jaar verlengen.",
   ["Probleemanalyse binnen 6 weken en plan van aanpak in week 8", "Ziekmelding UWV week 42 en eerstejaarsevaluatie", "Re-integratieverslag week 91", "Sanctie: verlenging loondoorbetaling tot een jaar"])
op("hrm4-go1", W, G, "Leg het verschil uit tussen een functioneringsgesprek, een beoordelingsgesprek en een ontwikkelgesprek. Let op richting, onderwerp en gevolgen.",
   "Functioneringsgesprek: tweerichtingsverkeer en gelijkwaardig, over hoe het werk gaat, wat de medewerker nodig heeft en hoe je samenwerkt; geen oordeel met directe gevolgen. Beoordelingsgesprek: van leidinggevende naar medewerker, een oordeel over de prestaties van de afgelopen periode; kan gevolgen hebben voor beloning of contract. Ontwikkelgesprek: tweerichtingsverkeer en toekomstgericht, over talenten, ambities, loopbaan en duurzame inzetbaarheid; eindigt met afspraken over ontwikkelacties, bijvoorbeeld in een POP.",
   ["Functioneringsgesprek juist (richting, onderwerp, geen directe gevolgen)", "Beoordelingsgesprek juist (oordeel, gevolgen)", "Ontwikkelgesprek juist (toekomst, ambities, afspraken)"])
op("hrm4-go2", W, G, "Beschrijf de structuur van het inhoudelijke deel van een ontwikkelgesprek en formuleer bij elke stap een vraag die je zou stellen.",
   "1. Huidige situatie: 'Hoe kijk je terug op het afgelopen jaar? Waar haal je energie uit?' 2. Ontwikkelmogelijkheden: 'Welke kennis of vaardigheden zou je willen versterken?' 3. Toekomstperspectief: 'Waar zie je jezelf over drie tot vier jaar?' 4. Acties: 'Wat spreken we concreet af, en wanneer kijken we terug?'",
   ["Vier stappen in de juiste volgorde", "Bij elke stap een passende open vraag", "Afsluiting met concrete actie"])

# ---------- Casussen ----------
cs("hrm4-hc1", W, H, "Een gedemotiveerd cateringteam",
   "Je bent facility manager bij een groot kantoor. Het cateringteam van tien medewerkers is net samengevoegd uit twee locaties. Je merkt: er is veel discussie over wie welke taken doet, medewerkers klagen dat 'de anderen' de makkelijke diensten krijgen, en het werk is eentonig: elke dag dezelfde broodjes klaarmaken. Twee ervaren medewerkers zeggen dat ze 'toch nooit iets te zeggen hebben'.",
   [("Welke motivatietheorieën helpen je te begrijpen wat hier speelt? Noem er twee en koppel ze aan de casus.",
     "Billijkheidstheorie: medewerkers vergelijken zich met de anderen en vinden de verdeling oneerlijk. Zelfdeterminatietheorie: weinig autonomie ('nooit iets te zeggen'), en door de samenvoeging is de verbondenheid nog laag. Ook het taakkenmerkenmodel past: het werk mist afwisseling.",
     ["Twee passende theorieën", "Elke theorie gekoppeld aan een signaal uit de casus"]),
    ("Kies drie interventies van de interventiekaart en leg uit waarom ze hier passen.",
     "Taakroulatie of taakverbreding tegen de eentonigheid (afwisselend broodjes, kassa, vergaderservice). Participatief leiderschap: het team samen het rooster laten maken, wat ook de verdeling eerlijker maakt. Taakverrijking voor de twee ervaren medewerkers, bijvoorbeeld verantwoordelijkheid voor het menu of de inkoop. Persoonlijke erkenning voor goed werk.",
     ["Drie interventies van de kaart", "Elke interventie past bij een probleem uit de casus"]),
    ("In welke fase van teamontwikkeling zit het team waarschijnlijk, en wat doe je als leidinggevende?",
     "Waarschijnlijk storming (gangbare indeling van Tuckman): er is strijd over rollen en taken. Als leidinggevende maak je de rolverdeling en afspraken expliciet, zodat het team naar norming kan, bespreek je de spanningen open en stel je een gemeenschappelijk doel. Je stuurt in deze fase meer dan later.",
     ["Storming herkend met reden", "Concrete acties richting afspraken en normen (norming)"])])
cs("hrm4-ac1", W, A, "De vakantie van Ad",
   "Ad werkt 4 dagen van 8 uur per week als technisch medewerker bij een facilitair bedrijf. In zijn contract staan 14 vakantiedagen per jaar. In januari vraagt hij schriftelijk drie weken vakantie aan in juli. Na drie weken heeft hij nog niets gehoord. In mei zegt de werkgever dat de vakantie niet doorgaat, 'omdat het in juli druk is'. Tijdens een eerdere vakantie was Ad een week ziek; de werkgever heeft die week als vakantie afgeschreven. Ook stelt de werkgever voor om zijn wettelijke vakantiedagen 'af te kopen'.",
   [("Klopt het aantal vakantiedagen in het contract?",
     "Nee. Het wettelijke minimum is 4 keer de wekelijkse arbeidsduur (art. 7:634 BW): 4 × 32 uur = 128 uur, 16 dagen. 14 dagen is te weinig. De vakantieregeling is dwingend recht (art. 7:645 BW), dus Ad heeft recht op minimaal 16 dagen.",
     ["Nee, minimaal 16 dagen (128 uur)", "Berekening 4 × arbeidsduur per week"]),
    ("Mag de werkgever de vakantie in juli weigeren?",
     "Nee. Reageert de werkgever niet binnen twee weken schriftelijk op een vakantieverzoek, dan staat de vakantie vast volgens de wens van de werknemer (art. 7:638 lid 2 BW). Verschuiven na vaststelling kan alleen bij gewichtige redenen, en dan moet de werkgever de schade vergoeden (lid 5). Drukte in juli is waarschijnlijk geen gewichtige reden, want dat is voorzienbaar.",
     ["Niet binnen twee weken gereageerd: vakantie staat vast (lid 2)", "Verschuiven alleen bij gewichtige redenen, met schadevergoeding (lid 5)"]),
    ("Mocht de werkgever de ziekteweek als vakantie afschrijven, en mag hij de wettelijke dagen afkopen?",
     "Nee. Ziek tijdens vakantie telt niet als vakantie, tenzij de werknemer instemt (art. 7:638 lid 8 BW); vooraf in het contract kan dat alleen voor bovenwettelijke dagen (art. 7:637). Wettelijke dagen mogen tijdens het dienstverband niet worden afgekocht, bovenwettelijke wel (art. 7:640 BW).",
     ["Ziekte tijdens vakantie: geen vakantie zonder instemming", "Wettelijke dagen niet afkopen (7:640)"])])
cs("hrm4-gc1", W, G, "De vastgelopen receptioniste",
   "Je bent facility manager. Receptioniste Ingrid werkt al twaalf jaar aan dezelfde balie. Ze doet haar werk goed, maar collega's merken dat ze minder enthousiast is. Ze reageert kortaf op nieuwe ideeën, zoals de digitale bezoekersregistratie. In het vorige ontwikkelgesprek spraken jullie af 'dat ze eens naar een cursus zou kijken'; daar is niets van gekomen. Je plant een ontwikkelgesprek.",
   [("Wat bereid je voor, over Ingrid en over de organisatie?",
     "Over Ingrid: haar sterke punten (ervaring, kent iedereen, betrouwbaar), ontwikkelpunten (omgang met digitale veranderingen), mogelijke ambities en de eerdere, te vage afspraak. Over de organisatie: mogelijkheden voor groei, opleidingen (bijvoorbeeld rond digitale registratie), nieuwe taken en doorgroeimogelijkheden. Kernvraag: waar staat ze nu, en waar zou ze over drie tot vier jaar kunnen staan? Plan een rustige plek en genoeg tijd.",
     ["Voorbereiding over de medewerker (sterk, ontwikkel, ambitie, eerdere afspraak)", "Voorbereiding over de organisatie (opleiding, taken, doorgroei)"]),
    ("Formuleer bij elk van de vier stappen van het gesprek een vraag aan Ingrid.",
     "Huidige situatie: 'Hoe ervaar je je werk aan de balie op dit moment?' Ontwikkelmogelijkheden: 'Wat zou je werk voor jou weer interessanter maken?' Toekomstperspectief: 'Waar zie je jezelf over een paar jaar, hier of ergens anders?' Acties: 'Wat zou een eerste concrete stap kunnen zijn, en wanneer?'",
     ["Vier vragen, één per stap", "Open en niet beschuldigend geformuleerd"]),
    ("Hoe zorg je dat het dit keer niet bij een vage afspraak blijft?",
     "Maak een SMART-afspraak: bijvoorbeeld 'Ingrid volgt vóór 1 april de training digitale bezoekersregistratie en wordt daarna aanspreekpunt voor collega's.' Leg die vast, bijvoorbeeld in een POP, en plan een datum om terug te kijken. Omdat de vorige afspraak niet is nagekomen, benoem je dat open; komt het weer niet van de grond, dan is het tijd om te confronteren: duidelijk zeggen wat je verwacht en haar verantwoordelijk houden.",
     ["SMART-afspraak geformuleerd", "Vastleggen en evaluatiemoment", "Eerdere afspraak benoemen of confronteren"])])
